// El navegador manda SKU y cantidad. NUNCA precios: los precios se
// resuelven contra el catálogo en "Price Order". Si confiáramos en el
// cliente, cualquiera compraría el sartén a un dólar editando la petición.
const b = $input.first().json.body || {};
const cust = b.customer || {};
const ship = b.shipping || {};
const items = Array.isArray(b.items) ? b.items : [];

// A throw here kills the run before Respond Order Number, and the storefront
// cannot tell that from a placed order -- both are HTTP 200 with an empty body.
// Found at assurance item 09. Rejections are now data, and Checkout Valid?
// routes them to a 400 that names the reason.
class Rejected extends Error {}
const fail = (msg) => { throw new Rejected(msg); };

const guarded = (fn) => {
  try { return fn(); }
  catch (e) {
    if (e instanceof Rejected) return [{ json: { checkout_valid: false, checkout_error: e.message } }];
    throw e;
  }
};

return guarded(() => {

const name = String(cust.full_name || '').trim();
const email = String(cust.email || '').trim().toLowerCase();
if (name.length < 2) fail('missing full_name');
if (!/^[^@\s]+@[^@\s]+\.[^@\s]+$/.test(email)) fail('invalid email');

const req = ['line1', 'city', 'state', 'postal_code'];
for (const f of req) {
  if (!String(ship[f] || '').trim()) fail('missing shipping.' + f);
}

if (items.length === 0) fail('empty cart');
if (items.length > 20) fail('too many line items');

const clean = items.map((it) => {
  const sku = String(it.sku || '').trim().toUpperCase();
  const qty = Number(it.qty);
  if (!sku) fail('line item without sku');
  if (!Number.isInteger(qty) || qty < 1 || qty > 10) fail('bad qty for ' + sku);
  return { sku, qty };
});

const merged = {};
for (const it of clean) merged[it.sku] = (merged[it.sku] || 0) + it.qty;

// Supplied by the storefront, reused across retries of one checkout attempt.
// A caller that omits it gets no protection from duplicates -- that is inherent
// to a client-supplied key, and the storefront always sends one.
const idem = String(b.idempotency_key || '').trim().slice(0, 100) || null;

return [{ json: {
  webhook: 'brasa-checkout',
  source_event_id: idem,
  customer: { full_name: name, email, phone: String(cust.phone || '').trim() },
  ship_to: {
    line1: String(ship.line1).trim(),
    line2: String(ship.line2 || '').trim() || null,
    city: String(ship.city).trim(),
    state: String(ship.state).trim(),
    postal_code: String(ship.postal_code).trim(),
    country: String(ship.country || 'US').trim()
  },
  items: Object.entries(merged).map(([sku, qty]) => ({ sku, qty })),
  checkout_valid: true
} }];
});

const catalog = {};
for (const row of $input.all()) {
  catalog[String(row.json.sku).toUpperCase()] = {
    product_name: row.json.product_name,
    unit_price: Number(row.json.price)
  };
}

const order = $('Validate Input').first().json;

// Validate Input already refused this one. Carry the refusal to Checkout Valid?
// rather than throwing on top of it.
if (order.checkout_valid === false) return [{ json: order }];

const unknown = [];
const lines = order.items.map((it) => {
  const p = catalog[it.sku];
  if (!p) { unknown.push(it.sku); return null; }
  return {
    sku: it.sku,
    product_name: p.product_name,
    unit_price: p.unit_price,
    qty: it.qty,
    line_total: Math.round(p.unit_price * it.qty * 100) / 100
  };
});

// An unknown or inactive sku is the caller's error and must be named as such.
// Prices are still never read from the request -- that is the point of this node.
if (unknown.length) return [{ json: { checkout_valid: false,
  checkout_error: 'unknown or inactive sku: ' + unknown.join(', ') } }];

const subtotal = Math.round(lines.reduce((s, l) => s + l.line_total, 0) * 100) / 100;
const shipping_cost = subtotal >= 75 ? 0 : 8;
const total = Math.round((subtotal + shipping_cost) * 100) / 100;

return [{ json: { ...order, lines, subtotal, shipping_cost, total, checkout_valid: true } }];

