// The same guard as the intake path: the row the claim returned is the only
// evidence that this approval is the first one and that the ticket exists.
// Zero rows -> no send.
//
// Zero rows does not distinguish 'already answered' from 'no such ticket'.
// Both are cases where this workflow must not email, which is what the guard
// is for, but the caller cannot tell them apart. Stated in DECISIONS.md.
const _c = $('Claim Ticket').first().json;
const row = Array.isArray(_c) ? _c[0] : _c;
if (!row || !row.id) return [];

// The recipient comes from the claimed ticket, never from the request. This
// webhook is unauthenticated and world-reachable, and until 2026-08-07 it
// emailed whatever address the caller put in `customer_email` -- an open relay
// out of a verified sending domain, gated only on knowing a ticket id.
// Verified: execution 387 built `to` from the request body for a ticket whose
// customer was someone else.
const cust = Array.isArray(row.bc_customers) ? row.bc_customers[0] : row.bc_customers;
if (!cust || !cust.email) return [];

const built = $('Build Approved Email').first().json;
return [{ json: { ...built, to: cust.email, ticket_id: row.id } }];

