parameters.jsCode:
// Everything arriving here came from a public, unauthenticated endpoint. Nothing
// below trusts its shape. Added at assurance item 09, where four probes showed
// what the absence of this node cost:
//   {"hello":"world"}      -> died three nodes later at Retrieve Products with
//                             "Could not find the function public.search_products
//                             without parameters" -- an error about the wrong thing
//                             entirely -- and the caller got 200 with no body.
//   a NUL in the message   -> Postgres refused the write, same 200-with-no-body.
//   no Email address field -> a bc_customers row with email = '' and an auto-sent
//                             reply addressed to nobody.
//   a 1.1 MB message       -> accepted, stored, and paid for with a model call.
const t0   = new Date().toISOString();   // first executable point of the run
const raw  = $input.first().json || {};
const body = raw.body || {};

const reject = (why) => [{ json: { intake_valid: false, intake_error: why, t0 } }];

// Two callers reach this node and their payloads are identical by design: Tally, which
// posts server-to-server, and the storefront's own JS, which copies Tally's shape. A shared
// secret only means anything on the first, because anything the browser sends is readable by
// anyone who opens the page. `webhookUrl` is what separates them, and the webhook node emits
// it already.
//
// Inert until BC_INTAKE_SECRET is set: a closed gate shipped before the Tally field exists
// would refuse every real intake. While unset it says so, so which state a run was in is a
// question the database answers rather than one somebody remembers.
const viaTally = String(raw.webhookUrl || '').indexOf('/brasa-intake') !== -1;
const expectedSecret = String($env.BC_INTAKE_SECRET || '');
if (viaTally && expectedSecret) {
  const sentSecret = ((body.data && Array.isArray(body.data.fields) ? body.data.fields : [])
    .find(f => f && f.label === 'Intake secret') || {}).value;
  if (String(sentSecret == null ? '' : sentSecret).trim() !== expectedSecret) {
    return reject('intake secret missing or wrong');
  }
}

const data = body.data;
if (!data || typeof data !== 'object') return reject('body.data is missing or is not an object');
const fields = data.fields;
if (!Array.isArray(fields)) return reject('body.data.fields is missing or is not an array');

const pick = (label) => {
  const f = fields.find(x => x && x.label === label);
  return f == null ? null : f.value;
};

// Control characters, zero-width characters and bidirectional overrides. A NUL is
// the one that actually breaks something; the rest are stripped because they let a
// message render as one thing to an agent and store as another.
const clean = (v) => String(v == null ? '' : v)
  .replace(/[\u0000-\u0008\u000B\u000C\u000E-\u001F\u007F]/g, '')
  .replace(/[\u200B-\u200F\u202A-\u202E\u2066-\u2069\uFEFF]/g, '')
  .trim();

const MAX_MESSAGE = 4000;

const name       = clean(pick('Full name')).slice(0, 200);
const email      = clean(pick('Email address')).toLowerCase().slice(0, 320);
const phone      = clean(pick('Phone number')).slice(0, 40);
const messageRaw = clean(pick('Message'));

// A reply cannot be delivered without an address, and a customer row keyed on ''
// collides with every other address-less submission.
if (!/^[^@\s]+@[^@\s]+\.[^@\s]+$/.test(email)) return reject('missing or invalid email address');

// The key the idempotency guarantee rests on. Without it the caller gets no
// protection from duplicates, so say so rather than proceeding quietly.
const eventId = clean(data.responseId) || clean(data.submissionId) || clean(body.eventId);
if (!eventId) return reject('no idempotency key on the event');

return [{ json: {
  t0,
  intake_valid:      true,
  customer_name:     name || 'Customer',
  customer_email:    email,
  phone,
  raw_message:       messageRaw.slice(0, MAX_MESSAGE),
  message_truncated: messageRaw.length > MAX_MESSAGE,
  original_length:   messageRaw.length,
  source_event_id:   eventId
} }];

// The message carried no question, so there is nothing to classify and no reason
// to pay for a classification. This emits the exact shape DeepSeek returns, with
// a zero usage block, so Parse DeepSeek Response runs unchanged on both paths and
// every node that references it by name keeps working.
//
// The ticket is still created, still escalated on no_substance, still in the queue
// with the customer's address. Nothing is lost -- that is the whole point, and it
// is why this is a skip and not a rejection.
return [{ json: {
  choices: [{ message: { content: JSON.stringify({
    intent:        'other',
    draft_reply:   '',
    confidence:    0,
    escalate_flag: true,
    context_used:  'None'
  }) } }],
  usage: { prompt_tokens: 0, completion_tokens: 0, total_tokens: 0 },
  skipped_classification: true
} }];

