// DeepSeek did not answer -- timed out, refused, or returned nothing usable.
// Emits the same envelope Canned Classification emits, for the same reason: every
// node downstream references DeepSeek API by name and must keep working. The empty
// draft_reply is deliberate; Parse escalates on empty_draft, so this can only ever
// produce a ticket a human answers, never an auto-sent reply.
//
// Added at assurance item 11, after one intake in twenty was lost this way.
return [{ json: {
  choices: [{ message: { content: JSON.stringify({
    intent:        'other',
    draft_reply:   '',
    confidence:    0,
    escalate_flag: true,
    context_used:  'Fallback \u2014 model unavailable'
  }) } }],
  usage: { prompt_tokens: 0, completion_tokens: 0, total_tokens: 0 },
  model_unavailable: true
} }];
